INSERT INTO public.shop_items (
  teacher_id, name, description, category, rarity, cost, diamond_cost, min_level, icon, image_url,
  source_anime, ability_mode, ability_key, ability_name, ability_description, ability_config,
  attr_forca, attr_destreza, attr_inteligencia, attr_carisma, attr_agilidade, attr_resistencia, is_active
)
SELECT
  t.id, c.name, c.description, c.category, c.rarity, c.cost, COALESCE(c.diamond_cost, 0), c.min_level, c.icon, c.image_url,
  c.source_anime, c.ability_mode, c.ability_key, c.ability_name, c.ability_description, COALESCE(c.ability_config, '{}'::jsonb),
  COALESCE(c.attr_forca, 0), COALESCE(c.attr_destreza, 0), COALESCE(c.attr_inteligencia, 0),
  COALESCE(c.attr_carisma, 0), COALESCE(c.attr_agilidade, 0), COALESCE(c.attr_resistencia, 0), true
FROM public.teachers t
CROSS JOIN catalog c
WHERE NOT EXISTS (
  SELECT 1
  FROM public.shop_items existing
  WHERE existing.teacher_id = t.id
    AND lower(existing.name) = lower(c.name)
);
